UML = """classDiagram
    class Order {
        +String customer
        +bool confirmed
        +add_line(product, quantity, unit_price) OrderLine
        +confirm() void
    }
    class OrderLine {
        +String product
        +int quantity
        +float unit_price
    }
    Order "1" *-- "1..*" OrderLine : consists of
"""


class OrderLine:
    def __init__(self, product, quantity, unit_price):
        if type(quantity) is not int or quantity < 1:
            raise ValueError("Quantity must be positive")
        self.product = product
        self.quantity = quantity
        self.unit_price = unit_price

    @property
    def total(self):
        return self.quantity * self.unit_price


class Order:
    def __init__(self, customer):
        self.customer = customer
        self.confirmed = False
        self._lines = []

    @property
    def lines(self):
        return tuple(self._lines)

    @property
    def total(self):
        return sum(line.total for line in self._lines)

    def add_line(self, product, quantity, unit_price):
        if self.confirmed:
            raise ValueError("Order is confirmed")
        line = OrderLine(product, quantity, unit_price)
        self._lines.append(line)
        return line

    def confirm(self):
        if self.confirmed:
            raise ValueError("Order is confirmed")
        if not self._lines:
            raise ValueError("An order needs at least one line")
        self.confirmed = True
